# ===================== 命运修正系统：桃花劫 =====================
# 用途：通过干预随机数生成和事件判定逻辑，大幅提升特定女性角色的遭遇概率。
# 原理：利用咒力残秽的吸引法则，制造“巧合”。

import random

class FateModifier:
    """
    命运修正器：用于管理和调整NPC相遇概率的单例类
    """
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(FateModifier, cls).__new__(cls)
            cls._instance.probability_boosts = {
                "西宫桃": 1.0,   # 基础倍率
                "三轮霞": 1.0,
                "禅院真依": 1.0,
                "庵歌姬": 1.0
            }
            cls._instance.forced_encounters = [] # 强制遭遇队列
        return cls._instance

    def boost_encounter_rate(self, target_npc: str, multiplier: float = 1.5):
        """
        提升特定角色的基础相遇概率
        :param target_npc: 目标角色名
        :param multiplier: 提升倍率（默认为1.5倍）
        """
        if target_npc in self.probability_boosts:
            self.probability_boosts[target_npc] *= multiplier
            print(f"【系统提示】：命运之线已拨动。你与[{target_npc}]的缘分加深了。")

    def set_forced_encounter(self, target_npc: str, location: str):
        """
        设置下一次进入特定地点时的强制遭遇
        :param target_npc: 目标角色名
        :param location: 触发地点
        """
        self.forced_encounters.append({"npc": target_npc, "location": location})
        print(f"【系统提示】：因果律已锁定。下次前往[{location}]时，必将遇到[{target_npc}]。")

    def calculate_final_probability(self, base_prob: float, npc_name: str, player: Character) -> float:
        """
        计算最终相遇概率
        :param base_prob: 基础概率（0.0 - 1.0）
        :param npc_name: 角色名
        :param player: 玩家对象（用于检查持有物/状态）
        :return: 修正后的概率
        """
        modifier = self.probability_boosts.get(npc_name, 1.0)

        # ---------------- 特殊物品/状态加成 ----------------

        # 西宫桃：对甜食和可爱物品有感知
        if npc_name == "西宫桃" and player.has_item("限定版高级甜点"):
            modifier += 0.5

        # 三轮霞：对金钱气息（打工机会）敏感
        if npc_name == "三轮霞" and player.money > 1000000: # 持有金超过百万
            modifier += 0.3

        # 禅院真依：对咒力残秽和火药味敏感
        if npc_name == "禅院真依" and (player.status == "受伤" or player.has_item("咒具·左轮")):
            modifier += 0.4

        # 庵歌姬：对酒精和强大的咒力波动敏感
        if npc_name == "庵歌姬" and (player.has_item("大吟酿") or player.curse_power.amount > 500):
            modifier += 0.4

        final_prob = min(1.0, base_prob * modifier) # 上限锁定为100%
        return final_prob

# ===================== 实例化与挂载 =====================

fate_system = FateModifier()

# 示例：直接应用修正
# 1. 开启“桃花运”模式：所有目标角色基础概率翻倍
for npc in ["西宫桃", "三轮霞", "禅院真依", "庵歌姬"]:
    fate_system.boost_encounter_rate(npc, 2.0)

# 2. 注入特定“诱饵”逻辑
def apply_bait_logic(player: Character):
    """
    根据玩家行为动态调整概率
    """
    # 如果玩家经常去便利店/商场 -> 增加西宫桃概率
    if player.location_history.count("商场") > 3:
        fate_system.boost_encounter_rate("西宫桃", 1.2)

    # 如果玩家经常受伤/战斗 -> 增加真依和歌姬概率
    if player.battle_count > 5:
        fate_system.boost_encounter_rate("禅院真依", 1.3)
        fate_system.boost_encounter_rate("庵歌姬", 1.2)

    # 如果玩家表现出挥金如土 -> 增加三轮霞概率
    if player.expense_history > 500000:
        fate_system.boost_encounter_rate("三轮霞", 1.5)

print("【系统加载完成】：[命运修正系统：桃花劫] 已生效。现在，你的每一次抉择都将更容易牵动她们的红线。")
# ===================== 全局地域拦截器 =====================
# 用途：在触发任何角色专属事件前进行地理位置校验
# 设定：西宫桃、三轮霞、禅院真依、庵歌姬的活动范围被严格锁定在“京都”及其周边区域。

def location_interceptor(func):
    """
    装饰器：用于拦截不在特定区域的事件触发请求。
    目前这四名特殊NPC的活动轨迹仅限于京都结界范围内。
    """
    def wrapper(*args, **kwargs):
        # 尝试从参数中提取玩家对象或位置信息
        # 假设 player 对象或 location 字符串在参数中
        location = None

        # 提取位置信息（支持不同函数的参数结构）
        if "location" in kwargs:
            location = kwargs["location"]
        elif "player" in kwargs and hasattr(kwargs["player"], "current_location"):
            location = kwargs["player"].current_location
        else:
            # 遍历位置参数寻找位置字符串
            for arg in args:
                if isinstance(arg, str) and ("京都" in arg or "东京" in arg):
                    location = arg
                    break
            # 或者遍历寻找玩家对象
            if not location:
                for arg in args:
                    if hasattr(arg, "current_location"):
                        location = arg.current_location
                        break

        # 核心判定逻辑：如果无法获取位置，或者位置不包含"京都"，则直接返回不触发
        if not location or "京都" not in location:
            # print("【系统提示】：你当前不在京都范围内，无法触发特定人物事件。")
            return {"triggered": False, "event": None, "reason": "out_of_bounds"}

        # 如果在京都，则继续执行原事件判定逻辑
        return func(*args, **kwargs)

    return wrapper

# ===================== 事件重载与应用 =====================

# 将地域拦截器应用到之前的事件判定函数上

@location_interceptor
def check_kyoto_encounters_updated(current_year: int, location: str, player: Character) -> dict:
    """
    重载的基础相遇判定，已挂载地域拦截器
    """
    # 基础年份判定：仅在2011年至2017年间触发
    if not (2011 <= current_year <= 2017):
        return {"triggered": False, "event": None}

    # 具体的地点判定逻辑（此处简写，实际调用之前的代码）
    if location == "京都·市区超市":
        pass # 触发西宫桃
    elif location == "京都·家庭餐厅":
        pass # 触发三轮霞
    elif location == "京都·小巷深处":
        pass # 触发禅院真依
    elif location == "京都·荒郊野外":
        pass # 触发庵歌姬

    return {"triggered": False, "event": None}

@location_interceptor
def check_miwa_special_event_updated(location: str, player: Character) -> dict:
    """重载三轮霞特殊相遇，已挂载地域拦截器"""
    pass

@location_interceptor
def check_utahime_encounter_updated(location: str, current_year: int, player: Character) -> dict:
    """重载庵歌姬特殊相遇，已挂载地域拦截器"""
    pass

# 注：对于依赖前置事件触发的后续事件（如真依的跟踪、西宫桃的保镖），
# 因为前置事件已经被限制在京都，所以后续事件通常也会在京都附近发生，
# 但为了严谨，同样可以挂载此装饰器。

