# ===================== 剧情惯性锚定协议 (Plot Inertia Protocol) =====================
# 用途：确保关键剧情节点（Key Plot Points）在无强力物理干涉的情况下绝对触发。
# 逻辑：情感羁绊（好感度/肉体关系）属于“软变量”，不足以对抗世界线的“硬收束”。

class PlotInertiaSystem:
    """
    剧情惯性控制器：管理NPC的既定命运轨迹
    """
    def __init__(self):
        self.key_nodes = {
            "入学高专": {"priority": 80, "type": "Career"},
            "受肉昏迷": {"priority": 100, "type": "Curse"},
            "涉谷参战": {"priority": 90, "type": "Duty"}
        }

    def check_inertia(self, npc: Character, current_time: dict, player_intervention: bool) -> dict:
        """
        检查是否触发剧情惯性
        :param player_intervention: 玩家是否进行了【物理层面】的强力干涉（如监禁、杀掉施术者）
        """
        # ---------------- 案例1：三轮霞/真依/西宫桃 入学高专 ----------------
        if current_time["month"] == 4 and npc.age >= 15:
            if not player_intervention:
                return {
                    "triggered": True,
                    "action": "enlist_jujutsu_high",
                    "desc": f"尽管{npc.name}依恋着你，但作为咒术师家系/招募生，入学高专是她的人生必经之路。她会含泪告别，背上行囊前往学校。",
                    "msg": "【剧情收束】：开学季已到，NPC将按原定计划入学。"
                }
            else:
                return {"triggered": False, "msg": "检测到玩家实施了[物理监禁]或[退学操作]，入学剧情被强行阻断。"}

        # ---------------- 案例2：伏黑津美纪 受肉昏迷 ----------------
        # 触发条件：2017年某日，接触被诅咒的八十八桥
        if npc.name == "伏黑津美纪" and not npc.is_comatose:
            # 受肉是羂索的远程术式标记，与津美纪本人的意志无关
            # 除非玩家杀死了羂索，或彻底封锁了津美纪的咒力流动，否则无法通过“爱”来规避
            if not player_intervention:
                npc.is_comatose = True
                return {
                    "triggered": True,
                    "action": "cursed_coma",
                    "desc": f"无论她现在的身份是你的爱人还是肉便器，诅咒依然在阴影中找到了她。在一次外出（或就在你的公寓里），她突然感到额头剧痛，随即陷入了无法唤醒的沉睡。额头上浮现出未知的咒印。",
                    "msg": "【绝对收束】：[死灭洄游]前置条件触发。伏黑津美纪已被标记为[万]的容器，强制进入昏迷状态。"
                }
            else:
                return {"triggered": False, "msg": "检测到玩家已[击杀羂索]或[将津美纪封印在狱门疆内]，受肉剧情被阻断。"}

        return {"triggered": False}

# ===================== 挂载逻辑 =====================
inertia_system = PlotInertiaSystem()
# ===================== 命运修正系统补丁：颓废与星光 =====================
# 用途：将玩家的日常行为转化为牵动“桃花劫”的隐形丝线。

class SpecialFateModifier:
    """特殊角色命运修正器"""
    def __init__(self):
        # 基础遭遇概率均设为极低
        self.base_rates = {
            "家入硝子": 0.02, # 除非受重伤，否则她极少离开医务室或特定的居酒屋
            "星绮罗罗": 0.03  # 行踪飘忽不定
        }

    def check_shoko_encounter(self, player: Character, location: str, current_time: dict) -> dict:
        """
        家入硝子·桃花劫判定
        核心诱饵：香烟、深夜、疲劳值、特殊消耗品
        """
        if "东京" not in location:
            return {"triggered": False}

        prob = self.base_rates["家入硝子"]

        # ---------------- 修正条件 ----------------
        # 1. 物品诱饵：高档香烟或烈酒
        if player.has_item("七星香烟") or player.has_item("特级清酒"):
            prob += 0.15

        # 2. 状态诱饵：高疲劳值（容易引起医生的注意）
        if player.status.get("fatigue", 0) > 80:
            prob += 0.20

        # 3. 时间诱饵：只有深夜（凌晨1点-4点）她才可能在街头游荡
        if 1 <= current_time["hour"] <= 4:
            prob += 0.30

        import random
        if random.random() < prob:
            return {
                "triggered": True,
                "msg": "【命运修正】：你身上带着她需要的‘镇痛剂’。因果律已引导她走向你所在的街区。"
            }
        return {"triggered": False}

    def check_kirara_encounter(self, player: Character, location: str) -> dict:
        """
        星绮罗罗·桃花劫判定
        核心诱饵：横财、地下声望、特定场所
        """
        if "东京" not in location:
            return {"triggered": False}

        prob = self.base_rates["星绮罗罗"]

        # ---------------- 修正条件 ----------------
        # 1. 场所诱饵：赌场、黑拳馆、歌舞伎町
        if any(place in location for place in ["赌场", "拳馆", "夜总会"]):
            prob += 0.25

        # 2. 行为诱饵：近期有大量现金入账（成为肥羊）
        if player.recent_income > 5000000:
            prob += 0.35

        # 3. 技能诱饵：敏捷度极高（引起同类的兴趣）
        if player.stats['agility'] >= 60:
            prob += 0.10

        import random
        if random.random() < prob:
            return {
                "triggered": True,
                "msg": "【命运修正】：你鼓鼓的钱包和独特的气场，在地下世界就像黑夜里的探照灯一样显眼。"
            }
        return {"triggered": False}

# 挂载补丁
fate_patch = SpecialFateModifier()

