# ===================== 剧情惯性锚定协议 (Plot Inertia Protocol) =====================
# 用途：确保关键剧情节点（Key Plot Points）在无强力物理干涉的情况下绝对触发。
# 逻辑：情感羁绊（好感度/肉体关系）属于“软变量”，不足以对抗世界线的“硬收束”。

class PlotInertiaSystem:
    """
    剧情惯性控制器：管理NPC的既定命运轨迹
    """
    def __init__(self):
        self.key_nodes = {
            "入学高专": {"priority": 80, "type": "Career"},
            "受肉昏迷": {"priority": 100, "type": "Curse"},
            "涉谷参战": {"priority": 90, "type": "Duty"}
        }

    def check_inertia(self, npc: Character, current_time: dict, player_intervention: bool) -> dict:
        """
        检查是否触发剧情惯性
        :param player_intervention: 玩家是否进行了【物理层面】的强力干涉（如监禁、杀掉施术者）
        """
        # ---------------- 案例1：三轮霞/真依/西宫桃 入学高专 ----------------
        if current_time["month"] == 4 and npc.age >= 15:
            if not player_intervention:
                return {
                    "triggered": True,
                    "action": "enlist_jujutsu_high",
                    "desc": f"尽管{npc.name}依恋着你，但作为咒术师家系/招募生，入学高专是她的人生必经之路。她会含泪告别，背上行囊前往学校。",
                    "msg": "【剧情收束】：开学季已到，NPC将按原定计划入学。"
                }
            else:
                return {"triggered": False, "msg": "检测到玩家实施了[物理监禁]或[退学操作]，入学剧情被强行阻断。"}

        # ---------------- 案例2：伏黑津美纪 受肉昏迷 ----------------
        # 触发条件：2017年某日，接触被诅咒的八十八桥
        if npc.name == "伏黑津美纪" and not npc.is_comatose:
            # 受肉是羂索的远程术式标记，与津美纪本人的意志无关
            # 除非玩家杀死了羂索，或彻底封锁了津美纪的咒力流动，否则无法通过“爱”来规避
            if not player_intervention:
                npc.is_comatose = True
                return {
                    "triggered": True,
                    "action": "cursed_coma",
                    "desc": f"无论她现在的身份是你的爱人还是肉便器，诅咒依然在阴影中找到了她。在一次外出（或就在你的公寓里），她突然感到额头剧痛，随即陷入了无法唤醒的沉睡。额头上浮现出未知的咒印。",
                    "msg": "【绝对收束】：[死灭洄游]前置条件触发。伏黑津美纪已被标记为[万]的容器，强制进入昏迷状态。"
                }
            else:
                return {"triggered": False, "msg": "检测到玩家已[击杀羂索]或[将津美纪封印在狱门疆内]，受肉剧情被阻断。"}

        return {"triggered": False}

