# 用途：将玩家的日常行为转化为牵动“桃花劫”的隐形丝线。

class SpecialFateModifier:
    """特殊角色命运修正器"""
    def __init__(self):
        # 基础遭遇概率均设为极低
        self.base_rates = {
            "家入硝子": 0.02, # 除非受重伤，否则她极少离开医务室或特定的居酒屋
            "星绮罗罗": 0.03  # 行踪飘忽不定
        }

    def check_shoko_encounter(self, player: Character, location: str, current_time: dict) -> dict:
        """
        家入硝子·桃花劫判定
        核心诱饵：香烟、深夜、疲劳值、特殊消耗品
        """
        if "东京" not in location:
            return {"triggered": False}

        prob = self.base_rates["家入硝子"]

        # ---------------- 修正条件 ----------------
        # 1. 物品诱饵：高档香烟或烈酒
        if player.has_item("七星香烟") or player.has_item("特级清酒"):
            prob += 0.15

        # 2. 状态诱饵：高疲劳值（容易引起医生的注意）
        if player.status.get("fatigue", 0) > 80:
            prob += 0.20

        # 3. 时间诱饵：只有深夜（凌晨1点-4点）她才可能在街头游荡
        if 1 <= current_time["hour"] <= 4:
            prob += 0.30

        import random
        if random.random() < prob:
            return {
                "triggered": True,
                "msg": "【命运修正】：你身上带着她需要的‘镇痛剂’。因果律已引导她走向你所在的街区。"
            }
        return {"triggered": False}

    def check_kirara_encounter(self, player: Character, location: str) -> dict:
        """
        星绮罗罗·桃花劫判定
        核心诱饵：横财、地下声望、特定场所
        """
        if "东京" not in location:
            return {"triggered": False}

        prob = self.base_rates["星绮罗罗"]

        # ---------------- 修正条件 ----------------
        # 1. 场所诱饵：赌场、黑拳馆、歌舞伎町
        if any(place in location for place in ["赌场", "拳馆", "夜总会"]):
            prob += 0.25

        # 2. 行为诱饵：近期有大量现金入账（成为肥羊）
        if player.recent_income > 5000000:
            prob += 0.35

        # 3. 技能诱饵：敏捷度极高（引起同类的兴趣）
        if player.stats['agility'] >= 60:
            prob += 0.10

        import random
        if random.random() < prob:
            return {
                "triggered": True,
                "msg": "【命运修正】：你鼓鼓的钱包和独特的气场，在地下世界就像黑夜里的探照灯一样显眼。"
            }
        return {"triggered": False}

